      "влияние": "Тормозит синтез РНК с несколько меньшей силой, чем α-аматоксин, и усиливает гепато- и нефротоксическое действие."
    },
    {
      "вещество": "γ-Аматоксин и ε-Аматоксин",
      "содержание": "следовые количества (менее 0,01 % от сухого веса)",
      "влияние": "Обладают слабой ингибиторной активностью к РНК-полимеразам и вносят незначительный вклад в общую токсичность."
    },
    {
      "вещество": "Фаллотицины (α-, β-, γ- и фаллоидин)",
      "содержание": "0,01–0,05 % от сухого веса",
      "влияние": "Связываются с F-актином и разрушают цитоскелет клеток, нарушая проницаемость клеточных мембран."
    },
    {
      "вещество": "Виротоксин",
      "содержание": "неизвестно (следовые количества)",
      "влияние": "Слабо подавляет синтез мРНК и практически не участвует в летальном исходе отравления."
    },
    {
      "вещество": "Вода и органические вещества (хитин, маны, белки, аминокислоты)",
      "содержание": "≈ 90 % от свежего веса (вода); сухие вещества ≈ 10 %",
      "влияние": "Сам по себе инертен, но обеспечивает структуру плодового тела и служит субстратом для метаболической активности."
    }
  ]
}

{
  "гриб": "Amanita citrina (лимонный мухомор)",
  "состав": [
    {
      "вещество": "α-аматоксин (α-аманитин)",
      "содержание": "до 0,1–0,3 % от сухого веса (данные по популяциям разнятся; в некоторых образцах не обнаружен)",
      "влияние": "Блокирует РНК-полимеразу II эукариот, что останавливает синтез белка и приводит к гибели клеток печени и почек."
    },
    {
      "вещество": "β-аматоксин (β-аманитин)",
      "содержание": "неизвестно (содержится в тех же популяциях, где обнаружен α-аманитин, обычно в меньшем количестве)",
      "влияние": "Токсичен по тому же механизму, что и α-аманитин, но в ~10 раз слабее связывается с РНК-полимеразой II."
    },
    {
      "вещество": "Вода",
      "содержание": "~85–90 % от свежего веса",
      "влияние": "Не токсична; основной структурный компонент плодового тела."
    },
    {
      "вещество": "Хитин (полисахарид клеточной стенки)",
      "содержание": "~1–2 % от сухого веса (типично для базидиомицетов)",
      "влияние": "Практически не усваивается человеком; при разложении может давать следовые количества D-глюкамина."
    },
    {
      "вещество": "Белки и пептиды (в т.ч. структурные и ферментные)",
      "содержание": "~8–12 % от сухого веса",
      "влияние": "Являются антигенным субстратом; сами по себе в микродозах не оказывают выраженного токсического эффекта."
    },
    {
      "вещество": "Липиды (фосфолипиды, стеролы — эргостерол)",
      "содержание": "~2–4 % от сухого веса",
      "влияние": "Не оказывают специфического токсического действия; эргостерол провитамин D."
    },
    {
      "вещество": "Минеральные элементы (K, P, Mg, Na, Ca)",
      "содержание": "~2–4 % от сухого веса (преимущественно K и P)",
      "влияние": "В физиологических количествах не токсичны; участвуют в метаболизме клеток гриба."
    }
  ]
}

{
  "гриб": "мухомор серо-розовый (Amanita rubescens)",
  "состав": [
    {
      "вещество": "Мускарицин (muscarine)",
      "содержание": "≈ 0,004–0,02 % от сухого веса",
      "влияние": "Агонист мускариновых холинорецепторов: вызывает слюнотечение, слезотечение, брадикардию, бронхоспазм и рвоту."
    },
    {
      "вещество": "Иботеновая кислота (ibotenic acid)",
      "содержание": "мг/кг свежей массы (следовые количества, точная цифра варьирует по источникам)",
      "влияние": "Сильный эксайтаторный аминокислотный нейротоксин (агонист GluR/NMDA-рецепторов), вызывает судороги и возбуждение ЦНС."
    },
    {
      "вещество": "Мусцимол (muscimol)",
      "содержание": "следовое количество, < 10 мг/кг сухого веса",
      "влияние": "Агонист ГАМК-А-рецепторов: оказывает центральный седативный и противосудорожный эффект."
    },
    {
      "вещество": "Склероцистин (sclerocystin, циклогекса-L-пролин)",
      "содержание": "мг/кг сухого веса (точное значение не стандартизовано)",
      "влияние": "Циклический пептид со средней токсичностью, ингибирует клеточный рост и вызывает гастроинтестинальное расстройство."
    },
    {
      "вещество": "Пигменты (серо-розовые хроматопорофировые комплексы)",
      "содержание": "неизвестно (специфический количественный состав не стандартизован)",
      "влияние": "Окраска плодового тела; клинического токсического действия на человека не обнаружено."
    }
  ]
}

{
  "гриб": "Amanita caesarea (цезарский гриб, мухомор Цезаря, царский гриб)",
  "состав": [
    {
      "вещество": "Хитин",
      "содержание": "~15–25 % от сухого веса",
      "влияние": "Структурный полисахарид клеточных стенок; у человека практически не гидролизуется и выводится транзитом."
    },
    {
      "вещество": "Трегалоза",
      "содержание": "~10–20 % от сухого веса",
      "влияние": "Запасной дисахарид; в пищеварительном тракте гидролизуется до глюкозы и служит источником энергии."
    },
    {
      "вещество": "Белки (суммарные аминокислоты)",
      "содержание": "~3–5 % от свежего веса (~18–25 % от сухого веса)",
      "влияние": "Составляют питательную ценность гриба; аминокислотный профиль близок к белкам растений."
    },
    {
      "вещество": "Свободная глутаминовая кислота",
      "содержание": "значительная доля пула свободных аминокислот (доля в свободных АА не превышает ~20–30 %; абсолютное содержание неизвестно)",
      "влияние": "Активирует умами-рецепторы языка, придавая мясисто-суповой привкус."
    },
    {
      "вещество": "Эргостерол (мицостерол)",
      "содержание": "~2–5 мг/г сухого веса",
      "влияние": "Является провитамином D₂; при облучении УФ трансформируется в эргокальциферол и вносит вклад в синтез витамина D."
    },
    {
      "вещество": "Калий (K)",
      "содержание": "~2000–4000 мг/кг свежего веса",
      "влияние": "Поддерживает электролитный и осмотический баланс, участвует в работе нервной и мышечной систем."
    },
    {
      "вещество": "β-Глюканы (β-1,3/1,6-глюкан)",
      "содержание": "~5–10 % от сухого веса",
      "влияние": "Связываются с Dectin-1/TLR-рецепторами на иммунных клетках, оказывая иммуномодулирующее и лёгкое противовирусное действие."
    },
    {
      "вещество": "Липиды (фосфолипиды, жирные кислоты, стерины)",
      "содержание": "~1–2 % от свежего веса (~5–10 % от сухого веса)",
      "влияние": "Входят в состав мембран; после кулинарной обработки частично усваиваются и вносят вклад в энергетический обмен."
    },
    {
      "вещество": "Нуклеиновые кислоты (РНК, ДНК)",
      "содержание": "~1–3 % от сухого веса",
      "влияние": "Гидролизуются в кишечнике до нуклеотидов и пуринов; в пищевых дозах значимого токсического или фармакологического действия не оказывают."
    },
    {
      "вещество": "Аскорбиновая кислота (витамин C)",
      "содержание": "несколько мг/100 г свежего веса (точное значение неизвестно)",
      "влияние": "Антиоксидант; в пищевых количествах вносит незначительный вклад в суточную потребность в витамине C."
    }
  ]
}
